import java.util.*;

public class Main {
    static Map<String, String[]> rules = new HashMap<>();
    static Map<String, Integer> memo = new HashMap<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            String result = sc.next();
            String a = sc.next(), b = sc.next(), c = sc.next();
            rules.put(result, new String[]{a, b, c});
        }
        String target = sc.next();
        System.out.println(solve(target));
    }

    static int solve(String witch) {
        if (memo.containsKey(witch)) return memo.get(witch);
        if (!rules.containsKey(witch)) {
            memo.put(witch, 1);
            return 1;
        }
        String[] children = rules.get(witch);
        int[] s = new int[3];
        for (int i = 0; i < 3; i++) s[i] = solve(children[i]);
        Arrays.sort(s);
        // s[2] >= s[1] >= s[0]
        int result = Math.max(s[2], Math.max(1 + s[1], 2 + s[0]));
        memo.put(witch, result);
        return result;
    }
}

