/*
We model each witch type as a node.
There are base witches obtainable directly from normal Grief Seeds.
There are synthesis rules: combining two witches a,b can create witch c.
To perform one synthesis, we need 3 special Grief Seeds at that moment:
- one holding witch a
- one holding witch b
- one empty seed to receive c
After synthesis, only c remains, so peak seeds needed for this synthesis plan is:
max(seeds needed to prepare a, seeds needed to prepare b, final count 1, while combining both + one empty)

If A and B are different:
need max(dp[a], dp[b], 3), but more precisely while both exist simultaneously we need 2 occupied + 1 empty,
and if preparing one side while keeping the other, peaks compose to dp[a] + 1 or dp[b] + 1.
This leads to classic formula:
dp[c] = min over rules a+b->c of max(dp[a] + 1, dp[b] + 1, 3)

If a == b, impossible because same witch type cannot be in multiple seeds simultaneously.

Also direct extraction gives dp[base] = 1.

We compute minimum required seeds on a DAG? Not guaranteed. But values only decrease from INF via relaxation.
Use Floyd/Bellman-like repeated relaxation until stable; since transitions are monotone over finite states, SPFA-style queue works.

Actually formula depends only on current dp[a], dp[b], so we can relax edges from operands to result.
*/
public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Rule {
        int a, b, c;
        Rule(int a, int b, int c) {
            this.a = a; this.b = b; this.c = c;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);   // number of witch types
        int m = fs.nextInt();              // number of directly obtainable witches
        int k = fs.nextInt();              // number of synthesis rules
        int target = fs.nextInt() - 1;     // target witch

        int INF = 1_000_000_000;
        int[] dp = new int[n];
        Arrays.fill(dp, INF);

        for (int i = 0; i < m; i++) {
            int x = fs.nextInt() - 1;
            dp[x] = 1;
        }

        List<Rule> rules = new ArrayList<>();
        List<List<Integer>> uses = new ArrayList<>();
        for (int i = 0; i < n; i++) uses.add(new ArrayList<>());

        for (int i = 0; i < k; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            int c = fs.nextInt() - 1;
            if (a == b) continue; // cannot hold same witch in multiple seeds simultaneously
            Rule r = new Rule(a, b, c);
            int idx = rules.size();
            rules.add(r);
            uses.get(a).add(idx);
            uses.get(b).add(idx);
        }

        ArrayDeque<Integer> q = new ArrayDeque<>();
        boolean[] inq = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (dp[i] < INF) {
                q.add(i);
                inq[i] = true;
            }
        }

        while (!q.isEmpty()) {
            int x = q.poll();
            inq[x] = false;

            for (int ri : uses.get(x)) {
                Rule r = rules.get(ri);
                if (dp[r.a] == INF || dp[r.b] == INF) continue;

                int cand = Math.max(3, Math.max(dp[r.a] + 1, dp[r.b] + 1));
                if (cand < dp[r.c]) {
                    dp[r.c] = cand;
                    if (!inq[r.c]) {
                        inq[r.c] = true;
                        q.add(r.c);
                    }
                }
            }
        }

        System.out.println(dp[target] == INF ? -1 : dp[target]);
    }
}

