#define MAXW 1005
#define MAXN 1005

char witch[MAXW][50];
int nw = 0;
int rules[MAXN][4]; // rules[i] = {result, ing1, ing2, ing3}
int nr = 0;
int memo[MAXW];

int getWitch(char *name) {
    for (int i = 0; i < nw; i++)
        if (strcmp(witch[i], name) == 0) return i;
    strcpy(witch[nw], name);
    return nw++;
}

int cmp_desc(const void *a, const void *b) {
    return *(int*)b - *(int*)a;
}

int solve(int w) {
    if (memo[w] != -1) return memo[w];
    // Find rule for w
    int found = -1;
    for (int i = 0; i < nr; i++) {
        if (rules[i][0] == w) { found = i; break; }
    }
    if (found == -1) { memo[w] = 1; return 1; } // base witch
    int s[3];
    for (int j = 0; j < 3; j++) s[j] = solve(rules[found][j+1]);
    // sort descending
    qsort(s, 3, sizeof(int), cmp_desc);
    int res = s[0];
    if (s[1]+1 > res) res = s[1]+1;
    if (s[2]+2 > res) res = s[2]+2;
    memo[w] = res;
    return res;
}

