#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int a, b, c;
} Rule;

static int cmp_rule(const void *p, const void *q) {
    const Rule *x = (const Rule *)p;
    const Rule *y = (const Rule *)q;
    if (x->c != y->c) return x->c - y->c;
    if (x->a != y->a) return x->a - y->a;
    return x->b - y->b;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    Rule *rules = (Rule *)malloc(sizeof(Rule) * m);
    for (int i = 0; i < m; i++) {
        int x, y, z;
        scanf("%d %d %d", &x, &y, &z);
        x--; y--; z--;
        if (x > y) {
            int t = x; x = y; y = t;
        }
        rules[i].a = x;
        rules[i].b = y;
        rules[i].c = z;
    }

    int target;
    scanf("%d", &target);
    target--;

    qsort(rules, m, sizeof(Rule), cmp_rule);

    int *start = (int *)malloc(sizeof(int) * (n + 1));
    for (int i = 0; i <= n; i++) start[i] = 0;

    int idx = 0;
    for (int c = 0; c < n; c++) {
        start[c] = idx;
        while (idx < m && rules[idx].c == c) idx++;
    }
    start[n] = m;

    const int INF = 1e9;
    int *dp = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) dp[i] = INF;

    /* Base: an easily obtainable witch can be placed into one seed directly. */
    for (int i = 0; i < n; i++) dp[i] = 1;

    /* Repeated relaxation on DAG-like dependency over set size.
       Since a rule for c uses distinct witches a,b and same type cannot coexist,
       optimal value is:
       dp[c] = min(dp[c], max(dp[a], dp[b] + 1), max(dp[b], dp[a] + 1))
       which simplifies to max(max(dp[a], dp[b]), min(dp[a], dp[b]) + 1)
       = max(da, db) if da != db ? actually exact minimum schedule:
         if da == db -> da + 1
         else -> max(da, db)
       equivalently max(da, db, min(da, db) + 1).
    */

    int changed = 1;
    while (changed) {
        changed = 0;
        for (int c = 0; c < n; c++) {
            int best = dp[c];
            for (int i = start[c]; i < start[c + 1]; i++) {
                int a = rules[i].a;
                int b = rules[i].b;
                if (a == b) continue;
                int da = dp[a], db = dp[b];
                int need;
                if (da == db) need = da + 1;
                else need = (da > db ? da : db);
                if (need < best) best = need;
            }
            if (best < dp[c]) {
                dp[c] = best;
                changed = 1;
            }
        }
    }

    printf("%d\n", dp[target]);

    free(rules);
    free(start);
    free(dp);
    return 0;
}

